std::pair<
  common::optional<
    std::shared_ptr<types::ISomething>
  >,
  common::optional<DeserializationError>
> ParsePropertiesOfSomething(
  const nlohmann::json& json,
  bool additional_properties
) {
  common::optional<
    std::vector<
      std::shared_ptr<types::IInstance>
    >
  > the_instances;

  common::optional<std::shared_ptr<types::IPointer> > the_pointer;

  common::optional<std::shared_ptr<types::IJsonObjectOfName> > the_json_object_of_name;

  common::optional<std::vector<nlohmann::json> > the_mappings;

  common::optional<
    std::vector<
      std::shared_ptr<types::IListOf>
    >
  > the_lists;

  common::optional<
    std::tuple<
      std::shared_ptr<types::IListOf>,
      std::wstring
    >
  > the_pair;

  common::optional<DeserializationError> error(
    ParseProperties(
      json,
      properties::kMapOfSomething,
      additional_properties,
      [&](
        properties::OfSomething property,
        const nlohmann::json& value
      ) -> common::optional<DeserializationError> {
        switch (property) {
          case properties::OfSomething::kInstances:
            return ParseInto(
              the_instances,
              DeserializeList<
                std::shared_ptr<types::IInstance>
              >(
                value,
                additional_properties,
                DeserializeInstance
              )
            );
          case properties::OfSomething::kPointer:
            return ParseInto(
              the_pointer,
              DeserializePointer(
                value,
                additional_properties
              )
            );
          case properties::OfSomething::kJsonObjectOfName:
            return ParseInto(
              the_json_object_of_name,
              DeserializeJsonObjectOfName(
                value,
                additional_properties
              )
            );
          case properties::OfSomething::kMappings:
            return ParseInto(
              the_mappings,
              DeserializeList<
                nlohmann::json
              >(
                value,
                DeserializeJsonObject
              )
            );
          case properties::OfSomething::kLists:
            return ParseInto(
              the_lists,
              DeserializeList<
                std::shared_ptr<types::IListOf>
              >(
                value,
                additional_properties,
                DeserializeListOf
              )
            );
          case properties::OfSomething::kPair:
            return ParseInto(
              the_pair,
              DeserializeTuple2<
                std::shared_ptr<types::IListOf>,
                std::wstring
              >(
                value,
                [&additional_properties](const nlohmann::json& a_json) {
                  return DeserializeListOf(a_json, additional_properties);
                },
                DeserializeWstring
              )
            );
          default:
            throw UnexpectedPropertyLiteralError(
              "properties::OfSomething",
              property
            );
        }
      }
    )
  );

  if (error.has_value()) {
    return NoInstanceAndDeserializationError<
      std::shared_ptr<types::ISomething>
    >(
      std::move(*error)
    );
  }

  if (!the_instances.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<types::ISomething>
    >(
      L"The required property instances is missing"
    );
  }

  if (!the_pointer.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<types::ISomething>
    >(
      L"The required property pointer is missing"
    );
  }

  if (!the_json_object_of_name.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<types::ISomething>
    >(
      L"The required property jsonObjectOfName is missing"
    );
  }

  if (!the_mappings.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<types::ISomething>
    >(
      L"The required property mappings is missing"
    );
  }

  if (!the_lists.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<types::ISomething>
    >(
      L"The required property lists is missing"
    );
  }

  if (!the_pair.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<types::ISomething>
    >(
      L"The required property pair is missing"
    );
  }

  return std::make_pair(
    common::make_optional<
      std::shared_ptr<types::ISomething>
    >(
      // NOTE (mristin):
      // We deliberately do not use std::make_shared here to avoid an unnecessary
      // upcast.
      new types::Something(
        std::move(*the_instances),
        std::move(*the_pointer),
        std::move(*the_json_object_of_name),
        std::move(*the_mappings),
        std::move(*the_lists),
        std::move(*the_pair)
      )
    ),
    common::nullopt
  );
}

std::pair<
  common::optional<
    std::shared_ptr<types::ISomething>
  >,
  common::optional<DeserializationError>
> DeserializeSomething(
  const nlohmann::json& json,
  bool additional_properties
) {
  common::optional<DeserializationError> error(
    CheckJsonObject(json)
  );

  if (error.has_value()) {
    return NoInstanceAndDeserializationError<
      std::shared_ptr<types::ISomething>
    >(
      std::move(*error)
    );
  }

  return ParsePropertiesOfSomething(json, additional_properties);
}

/**
 * \brief De-serialize \p json and render the outcome as an expected value.
 *
 * \param json value to be de-serialized
 * \param additional_properties if not set, check that \p json contains
 * no additional properties
 * \param deserialize de-serializes the value
 * \return the de-serialized value, or the error
 */
template <typename T, typename DeserializeT>
common::expected<
  T,
  DeserializationError
> DeserializeFrom(
  const nlohmann::json& json,
  bool additional_properties,
  const DeserializeT& deserialize
) {
  common::optional<T> instance;
  common::optional<DeserializationError> error;

  std::tie(
    instance,
    error
  ) = deserialize(json, additional_properties);

  if (instance.has_value()) {
    return std::move(*instance);
  }

  if (!error.has_value()) {
    throw std::logic_error(
      "Unexpected null error when null instance."
    );
  }

  return common::make_unexpected(
    std::move(*error)
  );
}

common::expected<
  std::shared_ptr<types::IInstance>,
  DeserializationError
> InstanceFrom(
  const nlohmann::json& json,
  bool additional_properties
) {
  return DeserializeFrom<
    std::shared_ptr<types::IInstance>
  >(
    json,
    additional_properties,
    DeserializeInstance
  );
}

