/**
 * \brief Give out a failed serialization with \p cause as its message.
 *
 * \param cause human-readable description of the failure
 * \return no value, and the error
 */
std::pair<
  common::optional<nlohmann::json>,
  common::optional<SerializationError>
> NoJsonAndSerializationErrorWithCause(
  std::wstring cause
) {
  return std::make_pair<
    common::optional<nlohmann::json>,
    common::optional<SerializationError>
  >(
    common::nullopt,
    common::make_optional<SerializationError>(
      std::move(cause)
    )
  );
}

/**
 * \brief Give out a failed serialization with \p error.
 *
 * \param error of the serialization
 * \return no value, and the error
 */
std::pair<
  common::optional<nlohmann::json>,
  common::optional<SerializationError>
> NoJsonAndSerializationError(
  SerializationError error
) {
  return std::make_pair<
    common::optional<nlohmann::json>,
    common::optional<SerializationError>
  >(
    common::nullopt,
    common::make_optional<SerializationError>(
      std::move(error)
    )
  );
}

/**
 * \brief Put the value serialized under \p key of \p result, or give out
 * the error of the serialization, marked with \p property.
 *
 * We deliberately take the *result* of a serialization instead of the value
 * and the function which serializes it. The item serializers of a tuple vary
 * both in number and in type, so no signature taking the serializer could
 * serve every serialization; taking the result lets this single function
 * serve all of them.
 *
 * \param result object to be written to
 * \param key of the property in the JSON object
 * \param property which the key stands for, for the path of the error
 * \param serialized result of the serialization
 * \return the error, if the serialization failed
 */
common::optional<SerializationError> SerializeInto(
  nlohmann::json& result,
  const char* key,
  iteration::Property property,
  std::pair<
    common::optional<nlohmann::json>,
    common::optional<SerializationError>
  >&& serialized
) {
  if (serialized.second.has_value()) {
    serialized.second->path.segments.emplace_front(
      common::make_unique<iteration::PropertySegment>(property)
    );

    return std::move(serialized.second);
  }

  result[key] = std::move(*serialized.first);

  return common::nullopt;
}

/**
 * \brief Give the value out in the shape of a serialization which can fail.
 *
 * ``SerializeTuple{N}`` takes one item serializer per item, and the items of
 * a tuple differ in kind, so some of them can fail and some of them can not.
 * Lifting the ones which can not is what lets the tuple treat all of them
 * alike, without a normalizing lambda per kind at the call site.
 */
template <typename T>
std::pair<
  common::optional<nlohmann::json>,
  common::optional<SerializationError>
> AsFallible(T&& value) {
  return std::make_pair(
    common::make_optional<nlohmann::json>(std::forward<T>(value)),
    common::nullopt
  );
}

/**
 * @copybrief AsFallible
 *
 * The serialization could already fail, so there is nothing to lift.
 */
inline std::pair<
  common::optional<nlohmann::json>,
  common::optional<SerializationError>
> AsFallible(
  std::pair<
    common::optional<nlohmann::json>,
    common::optional<SerializationError>
  >&& serialized
) {
  return std::move(serialized);
}

/**
 * \brief Give out the instance behind \p pointer.
 *
 * The items of a tuple are heterogeneous, so ``SerializeTuple{N}`` can not
 * know which of them are instances -- held as a ``std::shared_ptr`` -- and
 * which are values. It asks per item instead, and this is the answer for
 * a pointer. See the overload for everything else.
 */
template <typename T>
const T& Deref(const std::shared_ptr<T>& pointer) {
  return *pointer;
}

/**
 * @copybrief Deref
 *
 * The item is the value itself, so there is nothing to dereference.
 */
template <typename T>
const T& Deref(const T& value) {
  return value;
}

std::pair<
  common::optional<nlohmann::json>,
  common::optional<SerializationError>
> SerializeJsonValue(
  const nlohmann::json& value
) {
  if (value.is_null() || value.is_binary() || value.is_discarded()) {
    return std::make_pair(
      common::nullopt,
      common::make_optional<SerializationError>(
        common::Concat(
          L"Expected a JSON-able value (a boolean, a number, a string, "
          L"an array or an object), but got a value of type: ",
          common::Utf8ToWstring(value.type_name())
        )
      )
    );
  }

  if (value.is_array()) {
    nlohmann::json result(nlohmann::json::array());
    result.get_ref<nlohmann::json::array_t&>().reserve(value.size());

    size_t index = 0;
    for (const nlohmann::json& item : value) {
      common::optional<nlohmann::json> serialized_item;
      common::optional<SerializationError> error;
      std::tie(serialized_item, error) = SerializeJsonValue(item);

      if (error.has_value()) {
        error->path.segments.emplace_front(
          common::make_unique<iteration::IndexSegment>(index)
        );

        return std::make_pair(common::nullopt, std::move(error));
      }

      result.push_back(std::move(*serialized_item));
      ++index;
    }

    return std::make_pair(std::move(result), common::nullopt);
  }

  if (value.is_object()) {
    nlohmann::json result(nlohmann::json::object());

    for (const auto& item : value.items()) {
      common::optional<nlohmann::json> serialized_value;
      common::optional<SerializationError> error;
      std::tie(serialized_value, error) = SerializeJsonValue(item.value());

      if (error.has_value()) {
        error->path.segments.emplace_front(
          common::make_unique<iteration::KeySegment>(
            common::Utf8ToWstring(item.key())
          )
        );

        return std::make_pair(common::nullopt, std::move(error));
      }

      result[item.key()] = std::move(*serialized_value);
    }

    return std::make_pair(std::move(result), common::nullopt);
  }

  // NOTE (mristin):
  // JSON knows neither an infinity nor a not-a-number, so we refuse both
  // instead of silently writing them out as ``null``, mirroring
  // ``SerializeDouble`` for the floating-point properties of the model.
  // The caller gives us an ``nlohmann::json`` which may well have been
  // constructed programmatically, so a non-finite number can reach us
  // even though no conformant parser would ever produce one.
  if (value.is_number_float() && !std::isfinite(value.get<double>())) {
    return std::make_pair<
      common::optional<nlohmann::json>,
      common::optional<SerializationError>
    >(
      common::nullopt,
      common::make_optional<SerializationError>(
        common::Concat(
          L"Expected a JSON-able value, but got the number ",
          std::to_wstring(value.get<double>()),
          L", which is neither finite nor representable in JSON"
        )
      )
    );
  }

  // NOTE (mristin):
  // The value is a boolean, a number or a string, all of which are already
  // JSON-able as-is.
  return std::make_pair(value, common::nullopt);
}

std::pair<
  common::optional<nlohmann::json>,
  common::optional<SerializationError>
> SerializeJsonArray(
  const nlohmann::json& value
) {
  if (!value.is_array()) {
    return std::make_pair(
      common::nullopt,
      common::make_optional<SerializationError>(
        common::Concat(
          L"Expected a JSON array, but got a value of type: ",
          common::Utf8ToWstring(value.type_name())
        )
      )
    );
  }

  return SerializeJsonValue(value);
}

std::pair<
  common::optional<nlohmann::json>,
  common::optional<SerializationError>
> SerializeJsonObject(
  const nlohmann::json& value
) {
  if (!value.is_object()) {
    return std::make_pair(
      common::nullopt,
      common::make_optional<SerializationError>(
        common::Concat(
          L"Expected a JSON object, but got a value of type: ",
          common::Utf8ToWstring(value.type_name())
        )
      )
    );
  }

  return SerializeJsonValue(value);
}

/**
 * Serialize a tuple of 2 item(s) to a JSON array.
 */
template <
  typename T0,
  typename T1,
  typename SerializeItemT0,
  typename SerializeItemT1
>
std::pair<
  common::optional<nlohmann::json>,
  common::optional<SerializationError>
> SerializeTuple2(
  const std::tuple<
    T0,
    T1
  >& value,
  SerializeItemT0&& serialize_item0,
  SerializeItemT1&& serialize_item1
) {
  nlohmann::json serialized = nlohmann::json::array();
  serialized.get_ptr<nlohmann::json::array_t*>()->reserve(
    2
  );

  common::optional<SerializationError> error;

  common::optional<nlohmann::json> json_item0;
  std::tie(
    json_item0,
    error
  ) = AsFallible(
    serialize_item0(
      Deref(std::get<0>(value))
    )
  );
  if (error.has_value()) {
    error->path.segments.emplace_front(
      common::make_unique<iteration::IndexSegment>(
        0
      )
    );
    return std::make_pair<
      common::optional<nlohmann::json>,
      common::optional<SerializationError>
    >(
      common::nullopt,
      std::move(error)
    );
  }

  serialized.emplace_back(
    std::move(*json_item0)
  );

  common::optional<nlohmann::json> json_item1;
  std::tie(
    json_item1,
    error
  ) = AsFallible(
    serialize_item1(
      Deref(std::get<1>(value))
    )
  );
  if (error.has_value()) {
    error->path.segments.emplace_front(
      common::make_unique<iteration::IndexSegment>(
        1
      )
    );
    return std::make_pair<
      common::optional<nlohmann::json>,
      common::optional<SerializationError>
    >(
      common::nullopt,
      std::move(error)
    );
  }

  serialized.emplace_back(
    std::move(*json_item1)
  );

  return std::make_pair(
    std::move(serialized),
    common::nullopt
  );
}

